CREATE TABLE IF NOT EXISTS "__EFMigrationsHistory" (
    "MigrationId" character varying(150) NOT NULL,
    "ProductVersion" character varying(32) NOT NULL,
    CONSTRAINT "PK___EFMigrationsHistory" PRIMARY KEY ("MigrationId")
);

START TRANSACTION;


DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261110072048_InitialPostgreSql') THEN
    CREATE TABLE public."GhiNhanTam" (
        "Id" integer GENERATED BY DEFAULT AS IDENTITY,
        "MaGhiNhan" text GENERATED ALWAYS AS (('GN' || CASE WHEN "Id" < 1000 THEN lpad("Id"::text, 3, '0') ELSE "Id"::text END)) STORED,
        "LichDayId" integer NOT NULL,
        "MaThietBi" text NOT NULL,
        "MoTa" text NOT NULL,
        "NguoiGhiId" integer NOT NULL,
        "ThoiGian" timestamp with time zone NOT NULL,
        "TrangThai" text NOT NULL,
        "TicketId" integer,
        CONSTRAINT "PK_GhiNhanTam" PRIMARY KEY ("Id"),
        CONSTRAINT "CK_GhiNhan_TrangThai" CHECK ("TrangThai" IN ('Chưa tổng hợp', 'Đã tạo Ticket'))
    );
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261110072048_InitialPostgreSql') THEN
    CREATE TABLE "NguoiDung" (
        "Id" integer GENERATED BY DEFAULT AS IDENTITY,
        "TenDangNhap" character varying(50) NOT NULL,
        "MatKhauHash" character varying(500) NOT NULL,
        "HoTen" character varying(100) NOT NULL,
        "VaiTro" varchar(5) NOT NULL,
        "HoatDong" boolean NOT NULL,
        CONSTRAINT "PK_NguoiDung" PRIMARY KEY ("Id"),
        CONSTRAINT "CK_NguoiDung_VaiTro" CHECK ("VaiTro" IN ('GV', 'KTV', 'QL'))
    );
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261110072048_InitialPostgreSql') THEN
    CREATE TABLE "Phong" (
        "MaPhong" character varying(20) NOT NULL,
        "LoaiPhong" character varying(20) NOT NULL,
        "Cum" varchar(10) NOT NULL,
        "SucChua" integer NOT NULL,
        CONSTRAINT "PK_Phong" PRIMARY KEY ("MaPhong"),
        CONSTRAINT "CK_Phong_Cum" CHECK ("Cum" IN ('F', 'G', 'AI')),
        CONSTRAINT "CK_Phong_Loai" CHECK ("LoaiPhong" IN ('PC', 'BYOD', 'Lab AI', 'CISCO')),
        CONSTRAINT "CK_Phong_SucChua" CHECK ("SucChua" > 0)
    );
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261110072048_InitialPostgreSql') THEN
    CREATE TABLE "LichDay" (
        "Id" integer GENERATED BY DEFAULT AS IDENTITY,
        "MaLich" character varying(10) GENERATED ALWAYS AS (('L' || CASE WHEN "Id" < 1000 THEN lpad("Id"::text, 3, '0') ELSE "Id"::text END)) STORED NOT NULL,
        "Ngay" date NOT NULL,
        "Ca" character varying(10) NOT NULL,
        "BatDau" time(0) without time zone NOT NULL,
        "KetThuc" time(0) without time zone NOT NULL,
        "MonHoc" character varying(150) NOT NULL,
        "MaPhong" character varying(20) NOT NULL,
        "GiangVienId" integer NOT NULL,
        "TrangThai" character varying(20) NOT NULL,
        "SoBuoi" integer NOT NULL,
        CONSTRAINT "PK_LichDay" PRIMARY KEY ("Id"),
        CONSTRAINT "CK_LichDay_Gio" CHECK ("BatDau" < "KetThuc"),
        CONSTRAINT "CK_LichDay_TrangThai" CHECK ("TrangThai" IN ('Chưa check-in', 'Đang diễn ra', 'Đã kết thúc')),
        CONSTRAINT "FK_LichDay_NguoiDung_GiangVienId" FOREIGN KEY ("GiangVienId") REFERENCES "NguoiDung" ("Id") ON DELETE RESTRICT,
        CONSTRAINT "FK_LichDay_Phong_MaPhong" FOREIGN KEY ("MaPhong") REFERENCES "Phong" ("MaPhong") ON DELETE RESTRICT
    );
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261110072048_InitialPostgreSql') THEN
    CREATE TABLE "ThietBi" (
        "MaThietBi" character varying(30) NOT NULL,
        "MaPhong" character varying(20) NOT NULL,
        "Loai" varchar(10) NOT NULL,
        "Ten" character varying(150) NOT NULL,
        "TrangThai" character varying(20) NOT NULL,
        CONSTRAINT "PK_ThietBi" PRIMARY KEY ("MaThietBi"),
        CONSTRAINT "CK_ThietBi_Loai" CHECK ("Loai" IN ('PC', 'TV', 'WIFI', 'TUSAC', 'KIT')),
        CONSTRAINT "CK_ThietBi_TrangThai" CHECK ("TrangThai" IN ('Sẵn sàng', 'Hỏng', 'Đang bảo trì')),
        CONSTRAINT "FK_ThietBi_Phong_MaPhong" FOREIGN KEY ("MaPhong") REFERENCES "Phong" ("MaPhong") ON DELETE RESTRICT
    );
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261110072048_InitialPostgreSql') THEN
    CREATE TABLE "NhatKyCheckIn" (
        "Id" integer GENERATED BY DEFAULT AS IDENTITY,
        "MaNhatKy" character varying(10) GENERATED ALWAYS AS (('NK' || CASE WHEN "Id" < 1000 THEN lpad("Id"::text, 3, '0') ELSE "Id"::text END)) STORED NOT NULL,
        "LichDayId" integer NOT NULL,
        "ThoiGianCheckIn" timestamp(0) without time zone NOT NULL,
        "CheckInMuon" boolean NOT NULL,
        "SoPhutTre" integer NOT NULL,
        "ThoiGianCheckOut" timestamp(0) without time zone,
        "DaTatDien" boolean,
        "DaKhoaCua" boolean,
        CONSTRAINT "PK_NhatKyCheckIn" PRIMARY KEY ("Id"),
        CONSTRAINT "CK_NhatKy_Gio" CHECK ("ThoiGianCheckOut" IS NULL OR "ThoiGianCheckOut" >= "ThoiGianCheckIn"),
        CONSTRAINT "FK_NhatKyCheckIn_LichDay_LichDayId" FOREIGN KEY ("LichDayId") REFERENCES "LichDay" ("Id") ON DELETE RESTRICT
    );
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261110072048_InitialPostgreSql') THEN
    CREATE TABLE "YeuCauDoiPhong" (
        "Id" integer GENERATED BY DEFAULT AS IDENTITY,
        "MaYeuCau" character varying(10) GENERATED ALWAYS AS (('YC' || CASE WHEN "Id" < 1000 THEN lpad("Id"::text, 3, '0') ELSE "Id"::text END)) STORED NOT NULL,
        "LichDayId" integer NOT NULL,
        "GiangVienId" integer NOT NULL,
        "PhongCu" character varying(20) NOT NULL,
        "PhongMoi" character varying(20) NOT NULL,
        "LyDo" character varying(500) NOT NULL,
        "Loai" character varying(20) NOT NULL,
        "TrangThai" character varying(20) NOT NULL,
        "ThoiGianTao" timestamp(0) without time zone NOT NULL,
        "NguoiDuyetId" integer,
        "ThoiGianDuyet" timestamp(0) without time zone,
        "GhiChuDuyet" character varying(500),
        CONSTRAINT "PK_YeuCauDoiPhong" PRIMARY KEY ("Id"),
        CONSTRAINT "CK_YeuCau_Loai" CHECK ("Loai" IN ('Có kế hoạch', 'Khẩn cấp')),
        CONSTRAINT "CK_YeuCau_Phong" CHECK ("PhongCu" <> "PhongMoi"),
        CONSTRAINT "CK_YeuCau_TrangThai" CHECK ("TrangThai" IN ('Chờ duyệt', 'Tự động duyệt', 'Đã duyệt', 'Từ chối')),
        CONSTRAINT "FK_YeuCauDoiPhong_LichDay_LichDayId" FOREIGN KEY ("LichDayId") REFERENCES "LichDay" ("Id") ON DELETE RESTRICT,
        CONSTRAINT "FK_YeuCauDoiPhong_NguoiDung_GiangVienId" FOREIGN KEY ("GiangVienId") REFERENCES "NguoiDung" ("Id") ON DELETE RESTRICT,
        CONSTRAINT "FK_YeuCauDoiPhong_NguoiDung_NguoiDuyetId" FOREIGN KEY ("NguoiDuyetId") REFERENCES "NguoiDung" ("Id") ON DELETE RESTRICT,
        CONSTRAINT "FK_YeuCauDoiPhong_Phong_PhongCu" FOREIGN KEY ("PhongCu") REFERENCES "Phong" ("MaPhong") ON DELETE RESTRICT,
        CONSTRAINT "FK_YeuCauDoiPhong_Phong_PhongMoi" FOREIGN KEY ("PhongMoi") REFERENCES "Phong" ("MaPhong") ON DELETE RESTRICT
    );
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261110072048_InitialPostgreSql') THEN
    CREATE TABLE "TicketSuCo" (
        "Id" integer GENERATED BY DEFAULT AS IDENTITY,
        "MaTicket" character varying(10) GENERATED ALWAYS AS (('TK' || CASE WHEN "Id" < 1000 THEN lpad("Id"::text, 3, '0') ELSE "Id"::text END)) STORED NOT NULL,
        "MaThietBi" character varying(30) NOT NULL,
        "LoaiLoi" character varying(100) NOT NULL,
        "GhiChu" character varying(1000),
        "NguoiBaoId" integer NOT NULL,
        "ThoiGianTao" timestamp(0) without time zone NOT NULL,
        "TrangThai" character varying(20) NOT NULL,
        "KtvXuLyId" integer,
        "ThoiGianCapNhat" timestamp(0) without time zone,
        "ThoiGianHoanTat" timestamp(0) without time zone,
        CONSTRAINT "PK_TicketSuCo" PRIMARY KEY ("Id"),
        CONSTRAINT "CK_Ticket_TrangThai" CHECK ("TrangThai" IN ('Chờ xử lý', 'Đang sửa chữa', 'Báo cáo cấp trên', 'Đã khắc phục')),
        CONSTRAINT "FK_TicketSuCo_NguoiDung_KtvXuLyId" FOREIGN KEY ("KtvXuLyId") REFERENCES "NguoiDung" ("Id") ON DELETE RESTRICT,
        CONSTRAINT "FK_TicketSuCo_NguoiDung_NguoiBaoId" FOREIGN KEY ("NguoiBaoId") REFERENCES "NguoiDung" ("Id") ON DELETE RESTRICT,
        CONSTRAINT "FK_TicketSuCo_ThietBi_MaThietBi" FOREIGN KEY ("MaThietBi") REFERENCES "ThietBi" ("MaThietBi") ON DELETE RESTRICT
    );
    END IF;
END $EF$;

