        "VaiTroNhan" varchar(5) NOT NULL,
        "NguoiNhanId" integer,
        "NguoiNhan" character varying(200) NOT NULL,
        "NoiDung" character varying(1000) NOT NULL,
        "ThoiGian" timestamp(0) without time zone NOT NULL,
        "TrangThai" character varying(30) NOT NULL,
        "YeuCauId" integer,
        CONSTRAINT "PK_ThongBao" PRIMARY KEY ("Id"),
        CONSTRAINT "FK_ThongBao_NguoiDung_NguoiNhanId" FOREIGN KEY ("NguoiNhanId") REFERENCES "NguoiDung" ("Id") ON DELETE RESTRICT,
        CONSTRAINT "FK_ThongBao_YeuCauDoiPhong_YeuCauId" FOREIGN KEY ("YeuCauId") REFERENCES "YeuCauDoiPhong" ("Id") ON DELETE RESTRICT
    );
    END IF;
END $EF$;

