DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261123060000_DeviceSurrogateKey') THEN
    ALTER TABLE public."TicketSuCo"
        DROP CONSTRAINT IF EXISTS "FK_TicketSuCo_ThietBi_MaThietBi";

    ALTER TABLE public."ThietBi"
        ADD COLUMN "Id" integer GENERATED BY DEFAULT AS IDENTITY;

    ALTER TABLE public."TicketSuCo"
        ADD COLUMN "ThietBiId" integer;

    UPDATE public."TicketSuCo" t
    SET "ThietBiId" = d."Id"
    FROM public."ThietBi" d
    WHERE d."MaThietBi" = t."MaThietBi";

    ALTER TABLE public."GhiNhanTam"
        ADD COLUMN "ThietBiId" integer;

    UPDATE public."GhiNhanTam" g
    SET "ThietBiId" = d."Id"
    FROM public."LichDay" l, public."ThietBi" d
    WHERE l."Id" = g."LichDayId"
      AND d."MaThietBi" = g."MaThietBi"
      AND d."MaPhong" = l."MaPhong";

    DO $$
    BEGIN
        IF EXISTS (SELECT 1 FROM public."TicketSuCo" WHERE "ThietBiId" IS NULL) THEN
            RAISE EXCEPTION 'DeviceSurrogateKey: Có Ticket không ánh xạ được sang thiết bị. Dừng migration để bảo toàn dữ liệu.';
        END IF;
        IF EXISTS (SELECT 1 FROM public."GhiNhanTam" WHERE "ThietBiId" IS NULL) THEN
            RAISE EXCEPTION 'DeviceSurrogateKey: Có GhiNhanTam không ánh xạ được theo thiết bị và phòng lịch dạy. Dừng migration để bảo toàn dữ liệu.';
        END IF;
    END $$;

    ALTER TABLE public."TicketSuCo" ALTER COLUMN "ThietBiId" SET NOT NULL;
    ALTER TABLE public."GhiNhanTam" ALTER COLUMN "ThietBiId" SET NOT NULL;

    DROP INDEX IF EXISTS public."IX_Ticket_MaThietBi";
    ALTER TABLE public."ThietBi" DROP CONSTRAINT "PK_ThietBi";
    ALTER TABLE public."ThietBi" ADD CONSTRAINT "PK_ThietBi" PRIMARY KEY ("Id");
    CREATE UNIQUE INDEX "UQ_ThietBi_MaPhong_MaThietBi"
        ON public."ThietBi" ("MaPhong", "MaThietBi");

    ALTER TABLE public."TicketSuCo"
        ADD CONSTRAINT "FK_TicketSuCo_ThietBi_ThietBiId"
        FOREIGN KEY ("ThietBiId") REFERENCES public."ThietBi" ("Id") ON DELETE RESTRICT;
    ALTER TABLE public."GhiNhanTam"
        ADD CONSTRAINT "FK_GhiNhanTam_ThietBi_ThietBiId"
        FOREIGN KEY ("ThietBiId") REFERENCES public."ThietBi" ("Id") ON DELETE RESTRICT;

    CREATE INDEX "IX_Ticket_ThietBiId" ON public."TicketSuCo" ("ThietBiId");

    ALTER TABLE public."TicketSuCo" DROP COLUMN "MaThietBi";
    ALTER TABLE public."GhiNhanTam" DROP COLUMN "MaThietBi";
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261123060000_DeviceSurrogateKey') THEN
    INSERT INTO "__EFMigrationsHistory" ("MigrationId", "ProductVersion")
    VALUES ('20261123060000_DeviceSurrogateKey', '8.0.11');
    END IF;
END $EF$;
COMMIT;

